constexpr int32_t kDitherMask = 63; // tile is 64x64, indexed by absolute coords

// ---------------------------------------------------------------------------
// sRGB encode table
// ---------------------------------------------------------------------------
// Indexed by the raw fp16 bit pattern, so the conversion is a load rather than
// a pow() per channel per pixel. Values are 8.8 fixed point (code * 256), which
// lets the dither be a single add and the rounding a single shift:
//
//     out = (table[half] + ditherValue) >> 8
//
// With table <= 255*256 = 65280 and dither <= 255, the sum tops out at exactly
// 65535 — so it cannot overflow uint16 and needs no clamp on the hot path.
//
// Only half patterns for [0,1] get an entry (0x0000..0x3C00, 15361 of them);
// everything else is folded in srgbFixed below.
constexpr uint32_t kSrgbTableSize = 0x3C00 + 1;

inline const uint16_t* srgbTable()
{
    static const uint16_t* const table = []
    {
        auto* t = new uint16_t[kSrgbTableSize];
        for (uint32_t bits = 0; bits < kSrgbTableSize; ++bits)
        {
            const float linear = drawing::detail::halfToFloat(uint16_t(bits));
            // Scale in double: the curve is float, but rounding the product in
            // float lands on the wrong side of a tie often enough to matter,
            // and this runs once.
            const double srgb = drawing::linearToSRGB01(linear);
            t[bits] = uint16_t(srgb * 255.0 * 256.0 + 0.5);
        }
        return t;
    }();
    return table;
}

// One channel, fp16 bit pattern -> 8.8 fixed-point sRGB.
//
// Out-of-range patterns are folded rather than rejected: negatives (including
// -0.0) to black, anything >= 1.0 to white. Infinities and NaNs have patterns
// above 0x3C00 and so land on white — wrong, but bounded and deterministic,
// which beats indexing a table out of bounds.
inline uint32_t srgbFixed(const uint16_t* table, uint16_t half)
{
    if (half >= 0x8000u)  // sign bit set
        return 0;
    if (half >= 0x3C00u)  // >= 1.0, or inf/NaN
        return 255u << 8;
    return table[half];
}

// ---------------------------------------------------------------------------
// Surface descriptors
// ---------------------------------------------------------------------------
// Plain descriptors rather than the renderer's Surface type, so this header
// compiles with no knowledge of the backend and can be tested on its own.

// fp16 premultiplied linear RGBA, as backends/CpuGfx.h renders it. Stride is in
// PIXELS, and rows there are padded to a multiple of 8, so it is NOT the width —
// confusing the two shears the image diagonally.
struct SourceSurface
{
    const uint16_t* pixels{};
    int32_t stridePixels{};
    int32_t width{};
    int32_t height{};
};

// What the destination buffer's bytes mean. An enum from the start, because
// "a 10-bit path is the same code with a different encode" is only true if the
// encode is already a parameter.
enum class PixelEncoding
{
    Bgra8888, // bytes B,G,R,X. An X11 TrueColor visual on a little-endian server
              // reports masks R=0x00ff0000 G=0x0000ff00 B=0x000000ff, which is
              // this. Also what Direct2D calls 32bppPBGRA.
    Rgba8888, // bytes R,G,B,X.
};

struct DestSurface
{
    uint8_t* pixels{};
    int32_t bytesPerRow{}; // NOT width*4 in general
    int32_t width{};
    int32_t height{};
    PixelEncoding encoding{ PixelEncoding::Bgra8888 };
};

// ---------------------------------------------------------------------------
// The encode
// ---------------------------------------------------------------------------
// Converts one rectangle of src into dst, with dither.
//
// THE DITHER IS INDEXED BY ABSOLUTE DESTINATION COORDINATES, never by position
// within the rectangle. This is the most important line in the file: repainting
// a sub-rectangle must produce byte-identical pixels to a full repaint, or every
// partial redraw leaves a seam where the dither pattern jumps — a bug that shows
// up only when some unrelated widget invalidates a neighbouring region, and is
// correspondingly horrible to track down. Pinned by
// CpuPresent.DirtyRectInvariance.
//
// Alpha: the destination is opaque, so a premultiplied source composited over
// black means using the stored value AS-IS. Do not copy the un-premultiply from
// helpers/SavePng.h — that exists because PNG carries an alpha channel and this
// does not. Applying it here would brighten every translucent pixel (25%-alpha
// white would leave as 255 instead of 137).
inline void encodeDirtyRect(const SourceSurface& src, const DestSurface& dst, drawing::RectL rect)
{
    if (!src.pixels || !dst.pixels)
        return;

    // Clip to both surfaces — callers pass client-supplied rectangles.
    const int32_t left   = (std::max)(rect.left, int32_t(0));
    const int32_t top    = (std::max)(rect.top,  int32_t(0));
    const int32_t right  = (std::min)(rect.right,  (std::min)(src.width,  dst.width));
    const int32_t bottom = (std::min)(rect.bottom, (std::min)(src.height, dst.height));
    if (right <= left || bottom <= top)
        return;

    const uint16_t* table = srgbTable();
    const bool bgr = dst.encoding == PixelEncoding::Bgra8888;

    for (int32_t y = top; y < bottom; ++y)
    {
        const uint16_t* s = src.pixels + (size_t(y) * size_t(src.stridePixels) + size_t(left)) * 4;
        uint8_t* d = dst.pixels + size_t(y) * size_t(dst.bytesPerRow) + size_t(left) * 4;
        const uint8_t* ditherRow = kDitherTile + (size_t(y & kDitherMask) << 6);

        for (int32_t x = left; x < right; ++x, s += 4, d += 4)
        {
            // One threshold per PIXEL, shared by all three channels. Independent
            // per-channel noise would dither the chroma too, which reads as
            // coloured speckle; a shared threshold keeps the noise luminance-only.
            const uint32_t t = ditherRow[x & kDitherMask];

            const uint8_t r = uint8_t((srgbFixed(table, s[0]) + t) >> 8);
            const uint8_t g = uint8_t((srgbFixed(table, s[1]) + t) >> 8);
            const uint8_t b = uint8_t((srgbFixed(table, s[2]) + t) >> 8);

            d[0] = bgr ? b : r;
            d[1] = g;
            d[2] = bgr ? r : b;
            d[3] = 0xFF; // opaque; X ignores it at depth 24, but leave it defined
        }
    }
}

